const m2="方向B总清单：服务大学生的95个平台，国内52+海外46去重2个重复（Payhip和Etsy两边都录了）。全部有实测记录：curl 107站次+Chrome渲染5站，不抄名单。A档42个信号确凿、B档28个真实信号弱、C档25个反爬需登录但公认真实。含学生付钱买什么全市场对照表（10类需求x国内/海外平台x实测价格），空白格=该市场国内没有对应平台正是海外独有机会。中国人最优4+1打法：留学文书润色（你就是过来人）、卖笔记分成（国内笔记英文化）、教中文（母语优势）、考试备考资料（GRE/GMAT亲身经验）+国内闲鱼小红书不用翻墙。";
const r = await tools.pwsh({
  description:"commit direction B master list",
  command:`cd "${P0}"; git -c http.proxy=http://127.0.0.1:7897 -c https.proxy=http://127.0.0.1:7897 add -A; git -c http.proxy=http://127.0.0.1:7897 -c https.proxy=http://127.0.0.1:7897 commit -m "${m1}" -m "${m2}"; git -c http.proxy=http://127.0.0.1:7897 -c https.proxy=http://127.0.0.1:7897 push origin main`,
  timeoutMs:180000
});
return { out: String((r.kind==='foreground'?r.stdout.text+r.stderr.text:r.output)||"").trim().slice(-100) };
